-- Scenario 021: staged assault evidence and canonical finale; remains NOT approved.
-- Sources are fictional narrative items; two independent origins, not automatic proof of an order.
DO $before$ BEGIN
 IF (SELECT count(*) FROM igr_private.igr_omerta_santoro_v25_drafts
 WHERE scenario_id='021' AND editorial_status='review' AND
 jsonb_array_length(manuscript->'canonical_truth'->'timeline')=2 AND jsonb_array_length(manuscript->'revelations')=1)<>3
 THEN RAISE EXCEPTION 'Unexpected 021 sources; no changes allowed'; END IF;
 IF (SELECT enabled FROM igr_private.igr_omerta_standalone_release_control WHERE id=1) IS DISTINCT FROM false
 THEN RAISE EXCEPTION 'Omerta release remains locked'; END IF;
END $before$;
CREATE TABLE IF NOT EXISTS igr_private.igr_omerta021_assault_backup_20261107 AS
SELECT scenario_id,variant_id,manuscript,content_md5,editorial_status
FROM igr_private.igr_omerta_santoro_v25_drafts WHERE scenario_id='021';
DO $backup$ BEGIN IF (SELECT count(*) FROM igr_private.igr_omerta021_assault_backup_20261107)<>3
THEN RAISE EXCEPTION 'Expected 3 backup variants';END IF;END $backup$;

WITH p AS (SELECT x FROM jsonb_array_elements('[{"variant":"A","documents":[{"id":"A-C3-03","what":"Le médecin des urgences a examiné le messager le soir de la remise. Son rapport décrit des contusions et une plaie au visage compatibles avec des coups. Il ne nomme aucun agresseur.","origin":"Service hospitalier indépendant — constat médical","independent_of":"Employé du restaurant et comptes du crew"},{"id":"A-C3-04","what":"Un employé du restaurant déclare avoir vu le soldat d’escorte entrer avec le messager. Depuis la porte de service, il a entendu Rinaldi ordonner de le frapper et vu le soldat lui porter des coups. Son récit doit être confronté aux autres témoignages.","origin":"Employé du restaurant — audition recueillie séparément","independent_of":"Service hospitalier et pièces financières"}],"limits":"Le rapport médical n''identifie pas de commanditaire. L''employé rapporte un ordre du Capo, mais le commandement doit aussi être confronté aux paroles du relais des consignes.","finale":"Rinaldi a ordonné les coups au messager pour détourner les soupçons de la seconde remise de 16 000 dollars ; le soldat chargé de l’escorte a exécuté l’ordre.","reveal":{"id":"021-A-C3-agression","kind":"guaranteed","audience":"investigation","min_cycle":"3","title":"L''ARRIÈRE-SALLE · CYCLE III","text":"Constat médical : Le médecin des urgences a examiné le messager le soir de la remise. Son rapport décrit des contusions et une plaie au visage compatibles avec des coups. Il ne nomme aucun agresseur.\nTémoignage : Un employé du restaurant déclare avoir vu le soldat d’escorte entrer avec le messager. Depuis la porte de service, il a entendu Rinaldi ordonner de le frapper et vu le soldat lui porter des coups. Son récit doit être confronté aux autres témoignages.","canonical_event_id":"A-C3-04","editorial_provenance":{"existing_events":["A-C3-03","A-C3-04"],"source_material":"Constat médical et témoignage d''un employé du restaurant","human_source_review":"pending","independent_of_optional_actions":"true"}}},{"variant":"B","documents":[{"id":"B-C3-03","what":"Un certificat établi après la convocation du messager consigne des blessures au visage compatibles avec une agression. Il ne permet ni d’identifier l’auteur ni de savoir si un ordre de violence a été donné.","origin":"Service hospitalier indépendant — constat médical","independent_of":"Employé du restaurant et comptes du crew"},{"id":"B-C3-04","what":"Un employé du restaurant affirme avoir entendu Rinaldi demander au soldat de « faire parler » le messager, sans entendre d’ordre explicite de le frapper. Il voit le soldat entrer avec lui et le frapper. Son audition ne permet pas d’exclure d’autres propos hors de sa présence.","origin":"Employé du restaurant — audition recueillie séparément","independent_of":"Service hospitalier et pièces financières"}],"limits":"Les blessures sont établies et le témoin attribue les coups au soldat. L’absence d''ordre entendu par un témoin ne démontre pas l''absence de tout ordre. Comparer les déclarations du Capo et du soldat.","finale":"Rinaldi avait exigé une explication, mais n’avait pas ordonné les coups. Le soldat d’escorte a frappé de sa propre initiative. Les 46 000 dollars ont été livrés en totalité à un dépôt autorisé.","reveal":{"id":"021-B-C3-agression","kind":"guaranteed","audience":"investigation","min_cycle":"3","title":"L''ARRIÈRE-SALLE · CYCLE III","text":"Constat médical : Un certificat établi après la convocation du messager consigne des blessures au visage compatibles avec une agression. Il ne permet ni d’identifier l’auteur ni de savoir si un ordre de violence a été donné.\nTémoignage : Un employé du restaurant affirme avoir entendu Rinaldi demander au soldat de « faire parler » le messager, sans entendre d’ordre explicite de le frapper. Il voit le soldat entrer avec lui et le frapper. Son audition ne permet pas d’exclure d’autres propos hors de sa présence.","canonical_event_id":"B-C3-04","editorial_provenance":{"existing_events":["B-C3-03","B-C3-04"],"source_material":"Constat médical et témoignage d''un employé du restaurant","human_source_review":"pending","independent_of_optional_actions":"true"}}},{"variant":"C","documents":[{"id":"C-C3-03","what":"Le constat médical du soir décrit des blessures au visage du messager compatibles avec des coups. Il ne permet pas de déduire qu’une somme d’argent a réellement disparu.","origin":"Service hospitalier indépendant — constat médical","independent_of":"Employé du restaurant et comptes du crew"},{"id":"C-C3-04","what":"Un employé du restaurant déclare avoir entendu Rinaldi ordonner au soldat de frapper le messager. Il a vu ce soldat le conduire dans l’arrière-salle et lui porter des coups. Son témoignage ne démontre pas que Rinaldi connaissait la fausse écriture comptable.","origin":"Employé du restaurant — audition recueillie séparément","independent_of":"Service hospitalier et pièces financières"}],"limits":"Le constat médical étaye les blessures, pas l''intention. Le récit du témoin doit être recoupé avec celui du relais. Rien ne montre que Rinaldi connaissait la fausse comptabilité.","finale":"Rinaldi a ordonné les coups au messager en croyant à la disparition de 10 000 dollars, que le comptable avait pourtant inventés dans ses écritures. Le soldat de l’escorte a exécuté cet ordre.","reveal":{"id":"021-C-C3-agression","kind":"guaranteed","audience":"investigation","min_cycle":"3","title":"L''ARRIÈRE-SALLE · CYCLE III","text":"Constat médical : Le constat médical du soir décrit des blessures au visage du messager compatibles avec des coups. Il ne permet pas de déduire qu’une somme d’argent a réellement disparu.\nTémoignage : Un employé du restaurant déclare avoir entendu Rinaldi ordonner au soldat de frapper le messager. Il a vu ce soldat le conduire dans l’arrière-salle et lui porter des coups. Son témoignage ne démontre pas que Rinaldi connaissait la fausse écriture comptable.","canonical_event_id":"C-C3-04","editorial_provenance":{"existing_events":["C-C3-03","C-C3-04"],"source_material":"Constat médical et témoignage d''un employé du restaurant","human_source_review":"pending","independent_of_optional_actions":"true"}}}]'::jsonb) x)
UPDATE igr_private.igr_omerta_santoro_v25_drafts m
SET manuscript=jsonb_set(m.manuscript,'{canonical_truth,timeline}',
  (m.manuscript->'canonical_truth'->'timeline') || (p.x->'documents'),true)
FROM p WHERE m.scenario_id='021' AND m.variant_id=p.x->>'variant' AND m.editorial_status='review';

