UPDATE igr_private.igr_omerta_santoro_v25_drafts m
SET manuscript=jsonb_set(m.manuscript,'{final_reveal}',
  to_jsonb(concat(m.manuscript->>'final_reveal',E'\n\nVIOLENCE AU RESTAURANT — ',p.x->>'finale')),true)
FROM p WHERE m.scenario_id='021' AND m.variant_id=p.x->>'variant' AND m.editorial_status='review';

UPDATE igr_private.igr_omerta_santoro_v25_drafts m
SET content_md5=md5(m.manuscript::text)
WHERE m.scenario_id='021' AND m.editorial_status='review';

UPDATE igr_private.igr_omerta_v29_c3_review c3
SET manuscript_md5=m.content_md5,review_status='review',reviewed_by=NULL,reviewed_at=NULL
FROM igr_private.igr_omerta_santoro_v25_drafts m
WHERE c3.scenario_id='021' AND m.scenario_id=c3.scenario_id AND m.variant_id=c3.variant_id;

UPDATE igr_private.igr_omerta_v29_precise_act_review g
SET source_manuscript_md5=m.content_md5,review_status='review',reviewed_by=NULL,reviewed_at=NULL
FROM igr_private.igr_omerta_santoro_v25_drafts m
WHERE g.scenario_id='021' AND m.scenario_id=g.scenario_id AND m.variant_id=g.variant_id;

UPDATE igr_private.igr_omerta_verdict_goal_axes g
SET manuscript_md5=m.content_md5,review_status='review',reviewed_by=NULL,reviewed_at=NULL
FROM igr_private.igr_omerta_santoro_v25_drafts m
WHERE g.scenario_id='021' AND m.scenario_id=g.scenario_id AND m.variant_id=g.variant_id;

UPDATE igr_private.igr_omerta_verdict_truth_actors a
SET manuscript_md5=m.content_md5,review_status='review',reviewed_by=NULL,reviewed_at=NULL
FROM igr_private.igr_omerta_santoro_v25_drafts m
WHERE a.scenario_id='021' AND m.scenario_id=a.scenario_id AND m.variant_id=a.variant_id;

UPDATE igr_private.igr_omerta_v29_indic_topics t
SET source_manuscript_md5=m.content_md5
FROM igr_private.igr_omerta_santoro_v25_drafts m
WHERE t.scenario_id='021' AND m.scenario_id=t.scenario_id AND m.variant_id=t.variant_id
AND t.review_status='pending';

DO $audit$ DECLARE n int; BEGIN
 SELECT count(*) INTO n FROM igr_private.igr_omerta_santoro_v25_drafts
 WHERE scenario_id='021' AND editorial_status='review' AND manuscript->>'human_review_approved'='false'
 AND jsonb_array_length(manuscript->'canonical_truth'->'timeline')=4
 AND jsonb_array_length(manuscript->'revelations')=2
 AND manuscript->'revelations'->1->'editorial_provenance'->>'human_source_review'='pending'
 AND content_md5=md5(manuscript::text);
 IF n<>3 THEN RAISE EXCEPTION '3 canonical briefs lost or proof wrongly approved: %',n; END IF;
 SELECT count(*) INTO n FROM igr_private.igr_omerta_v29_c3_review c
 JOIN igr_private.igr_omerta_santoro_v25_drafts m USING(scenario_id,variant_id)
 WHERE c.scenario_id='021' AND c.review_status='review' AND c.manuscript_md5=m.content_md5
 AND jsonb_array_length(c.sources)=2;
 IF n<>3 THEN RAISE EXCEPTION 'Financial C3 review mismatch: %',n; END IF;
 SELECT count(*) INTO n FROM igr_private.igr_omerta_v29_precise_act_review g
 JOIN igr_private.igr_omerta_santoro_v25_drafts m USING(scenario_id,variant_id)
 WHERE g.scenario_id='021' AND g.review_status='review' AND g.source_manuscript_md5=m.content_md5;
 IF n<>21 THEN RAISE EXCEPTION 'Precise acts hashes mismatch: %',n; END IF;
 SELECT count(*) INTO n FROM igr_private.igr_omerta_verdict_goal_axes g
 JOIN igr_private.igr_omerta_santoro_v25_drafts m USING(scenario_id,variant_id)
 WHERE g.scenario_id='021' AND g.review_status='review' AND g.manuscript_md5=m.content_md5;
 IF n<>21 THEN RAISE EXCEPTION 'Goal axes hashes mismatch: %',n; END IF;
 SELECT count(*) INTO n FROM igr_private.igr_omerta_verdict_truth_actors a
 JOIN igr_private.igr_omerta_santoro_v25_drafts m USING(scenario_id,variant_id)
 WHERE a.scenario_id='021' AND a.review_status='review' AND a.manuscript_md5=m.content_md5;
 IF n<>12 THEN RAISE EXCEPTION 'Truth actor hashes mismatch: %',n; END IF;
 IF (SELECT enabled FROM igr_private.igr_omerta_standalone_release_control WHERE id=1) IS DISTINCT FROM false
 THEN RAISE EXCEPTION 'Release gate changed!'; END IF;
END $audit$;